using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
namespace ApptyaKingdom {
 /// <summary>Functional first-pass HUD; replace with designed prefabs during UI art pass.</summary>
 public class ApptyaRuntimeHud:MonoBehaviour {
  Text stats,notice; Font font;
  void Start(){font=Resources.GetBuiltinResource<Font>("Arial.ttf");var cg=new GameObject("Apptya Canvas",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));cg.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceOverlay;cg.GetComponent<CanvasScaler>().uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;cg.GetComponent<CanvasScaler>().referenceResolution=new Vector2(1080,1920);if(!FindObjectOfType<EventSystem>())new GameObject("EventSystem",typeof(EventSystem),typeof(StandaloneInputModule));var top=Panel(cg.transform,"Resource HUD",new Vector2(0,1),new Vector2(1,1),new Vector2(0,-110),new Vector2(0,190));stats=TextAt(top.transform,"Resources",new Vector2(.5f,.5f),Vector2.zero,new Vector2(1000,160),30,TextAnchor.MiddleCenter);var bot=Panel(cg.transform,"Action HUD",new Vector2(.5f,0),new Vector2(.5f,0),new Vector2(0,245),new Vector2(1020,500));ButtonAt(bot.transform,"Gather wood +25",new Vector2(-330,135),()=>{ApptyaGameState.Instance.Gather("wood",25);Say("Lumber camp delivered wood.");});ButtonAt(bot.transform,"Harvest food +30",new Vector2(0,135),()=>{ApptyaGameState.Instance.Gather("food",30);Say("Farm delivered food.");});ButtonAt(bot.transform,"Train guard",new Vector2(330,135),()=>Say(ApptyaGameState.Instance.TrainGuard()?"A guard joined the army.":"Need 25 food and 10 gold."));ButtonAt(bot.transform,"Upgrade keep",new Vector2(-330,35),()=>Say(ApptyaGameState.Instance.UpgradeKeep()?"Keep upgraded!":"Need more wood and stone."));ButtonAt(bot.transform,"Scout wilds",new Vector2(0,35),()=>Say(ApptyaGameState.Instance.Scout()?"Scouts returned with loot.":"Train a guard first."));ButtonAt(bot.transform,"Upgrade lumber",new Vector2(-360,-65),()=>Upgrade("lumber","Lumber Camp"),220);ButtonAt(bot.transform,"Upgrade farm",new Vector2(-120,-65),()=>Upgrade("farm","Farmstead"),220);ButtonAt(bot.transform,"Upgrade barracks",new Vector2(120,-65),()=>Upgrade("barracks","Barracks"),220);ButtonAt(bot.transform,"Upgrade quarry",new Vector2(360,-65),()=>Upgrade("quarry","Quarry"),220);notice=TextAt(bot.transform,"Chronicle",new Vector2(.5f,.5f),new Vector2(0,-190),new Vector2(950,65),22,TextAnchor.MiddleCenter);ApptyaGameState.Instance.Changed+=Refresh;Refresh();}
  void OnDestroy(){if(ApptyaGameState.Instance!=null)ApptyaGameState.Instance.Changed-=Refresh;}
  void Refresh(){if(stats==null)return;var d=ApptyaGameState.Instance.Data;stats.text="APPTYA KINGDOM  |  KEEP "+d.keepLevel+"\nWOOD "+d.wood+"     FOOD "+d.food+"     STONE "+d.stone+"     GOLD "+d.gold+"     GUARDS "+d.guards;}
  void Say(string s){if(notice)notice.text=s;}\n  void Upgrade(string key,string label){var state=ApptyaGameState.Instance;int level=state.GetBuildingLevel(key);Say(state.UpgradeBuilding(key)?label+" upgraded to level "+(level+1)+"!":"Need "+(35*level)+" wood, "+(20*level)+" stone and "+(10*level)+" gold (max level 5).");}
  GameObject Panel(Transform p,string n,Vector2 amin,Vector2 amax,Vector2 pos,Vector2 size){var g=new GameObject(n,typeof(RectTransform),typeof(Image));g.transform.SetParent(p,false);var r=g.GetComponent<RectTransform>();r.anchorMin=amin;r.anchorMax=amax;r.anchoredPosition=pos;r.sizeDelta=size;g.GetComponent<Image>().color=new Color(.035f,.075f,.13f,.94f);return g;}
  Text TextAt(Transform p,string n,Vector2 a,Vector2 pos,Vector2 size,int fs,TextAnchor align){var g=new GameObject(n,typeof(RectTransform),typeof(Text));g.transform.SetParent(p,false);var r=g.GetComponent<RectTransform>();r.anchorMin=a;r.anchorMax=a;r.anchoredPosition=pos;r.sizeDelta=size;var t=g.GetComponent<Text>();t.font=font;t.fontSize=fs;t.alignment=align;t.color=Color.white;t.horizontalOverflow=HorizontalWrapMode.Wrap;return t;}
  void ButtonAt(Transform p,string label,Vector2 pos,UnityEngine.Events.UnityAction action,float width=300){var g=new GameObject(label,typeof(RectTransform),typeof(Image),typeof(Button));g.transform.SetParent(p,false);var r=g.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(.5f,.5f);r.anchoredPosition=pos;r.sizeDelta=new Vector2(width,78);g.GetComponent<Image>().color=new Color(.13f,.25f,.38f);g.GetComponent<Button>().onClick.AddListener(action);var tgo=new GameObject("Label",typeof(RectTransform),typeof(Text));tgo.transform.SetParent(g.transform,false);var tr=tgo.GetComponent<RectTransform>();tr.anchorMin=Vector2.zero;tr.anchorMax=Vector2.one;tr.offsetMin=tr.offsetMax=Vector2.zero;var t=tgo.GetComponent<Text>();t.font=font;t.fontSize=label.StartsWith("Upgrade ")&&width<300?17:22;t.fontStyle=FontStyle.Bold;t.alignment=TextAnchor.MiddleCenter;t.color=Color.white;t.text=label;}
 }
}